INSERT INTO `notifications` VALUES (7,'2026-10-12 10:14:14.135094',_binary '',15,'Dear Ezile Hlomane,\n\nGood news — \"Umlazi\" has been approved and is now live for students to view and apply to.',128,'Listing Approved: Umlazi',NULL),(8,'2026-10-13 16:15:28.176234',_binary '',15,'Dear Ezile Hlomane,\n\nGood news — \"Mercator\" has been approved and is now live for students to view and apply to.',99,'Listing Approved: Mercator',NULL),(9,'2026-10-14 02:05:43.541124',_binary '',15,'Dear Ezile Hlomane,\n\nThis serves as an official warning regarding \"Jordan River\". The following complaint(s) have been raised:\n\n• Safety: I would like to complain about the safety of the accommodation where I stay. The gate has been broken for several days, and no action has been taken to fix it. This is a serious safety concern because anyone could enter the accommodation without permission. I believe management should take this matter seriously and repair the gate as soon as possible to ensure the safety of all students living here.\n\nPlease address these issues promptly. Continued unresolved reports may result in suspension of this listing.',97,'Official Warning: Jordan River',NULL),(10,'2026-10-14 13:48:24.123215',_binary '\0',27,'Dear Lily Bloom,\n\nGood news — \"Sunset\" has been approved and is now live for students to view and apply to.',132,'Listing Approved: Sunset',NULL),(11,'2026-10-14 13:50:43.190520',_binary '\0',27,'Dear Lily Bloom,\n\n\"Apex\" was not approved.\n\nAdmin feedback: Dear Landlord,\r\n\r\nThank you for submitting your property for consideration. Unfortunately, we are unable to approve it for student accommodation because the proposed rental amount of **R20,000 per month** is too high for our target student market. We aim to provide affordable accommodation that students can realistically afford, and this price exceeds our budget requirements.\r\n\r\nWe appreciate your interest and thank you for your time and understanding.\r\n\r\nKind regards,  \r\nAccommodation Management Team\n\nOpen the listing from My Properties, fix these points and resubmit it.',131,'Listing Needs Changes: Apex',NULL),(12,'2026-10-14 13:51:13.040318',_binary '\0',27,'Dear Lily Bloom,\n\nGood news — \"The Dunes\" has been approved and is now live for students to view and apply to.',130,'Listing Approved: The Dunes',NULL),(13,'2026-10-14 15:23:14.263919',_binary '\0',15,'Aya Zulu has applied for \"Hector Pieterson Residence\".\n\nReview the application from your dashboard.',88,'New Application: Hector Pieterson Residence',NULL),(14,'2026-10-14 16:51:30.999265',_binary '\0',15,'Elsa Smith has applied for \"Gen Z\".\n\nReview the application from your dashboard.',100,'New Application: Gen Z',NULL),(15,'2026-10-14 16:52:23.723503',_binary '\0',15,'Elsa Smith has applied for \"Sanlam Student Village\".\n\nReview the application from your dashboard.',86,'New Application: Sanlam Student Village',NULL),(16,'2026-10-14 16:53:21.109676',_binary '\0',15,'Elsa Smith has applied for \"Amazing Grace\".\n\nReview the application from your dashboard.',111,'New Application: Amazing Grace',NULL),(17,'2026-10-14 16:55:37.157195',_binary '\0',15,'Anna Jobe has applied for \"Amazing Grace\".\n\nReview the application from your dashboard.',111,'New Application: Amazing Grace',NULL),(18,'2026-10-14 16:56:34.251027',_binary '\0',15,'Anna Jobe has applied for \"Gen Z\".\n\nReview the application from your dashboard.',100,'New Application: Gen Z',NULL),(19,'2026-10-14 16:58:47.424721',_binary '\0',15,'Aya Zulu has applied for \"Umlazi\".\n\nReview the application from your dashboard.',128,'New Application: Umlazi',NULL),(20,'2026-10-15 03:08:58.538590',_binary '\0',15,'Elsa Smith has applied for \"15 Admiralty\".\n\nReview the application from your dashboard.',89,'New Application: 15 Admiralty',NULL),(21,'2026-10-15 03:52:25.424383',_binary '\0',27,'Anna Jobe has applied for \"The Dunes\".\n\nReview the application from your dashboard.',130,'New Application: The Dunes',NULL),(22,'2026-10-15 05:24:43.778017',_binary '\0',15,'Odwa Mjoli has applied for \"Jordan River\".\n\nReview the application from your dashboard.',97,'New Application: Jordan River',NULL),(23,'2026-10-15 06:08:39.282541',_binary '\0',27,'Dear Lily Bloom,\n\nGood news — \"Mzansi\" has been approved and is now live for students to view and apply to.',133,'Listing Approved: Mzansi',NULL),(24,'2026-10-15 06:10:55.435068',_binary '\0',27,'Odwa Mjoli has applied for \"Mzansi\".\n\nReview the application from your dashboard.',133,'New Application: Mzansi',NULL),(25,'2026-10-15 08:47:02.218753',_binary '',15,'Odwa Mjoli has applied for \"16 Cardiff\".\n\nReview the application from your dashboard.',91,'New Application: 16 Cardiff',NULL),(26,'2026-10-15 18:34:49.071924',_binary '',15,'Elsa Smith has withdrawn their application for \"15 Admiralty\".\n\nThe application has been removed from your applications list.',89,'Application Withdrawn: 15 Admiralty',NULL),(27,'2026-10-15 21:11:18.695152',_binary '\0',15,'Anna Jobe has applied for \"Roch House\".\n\nReview the application from your dashboard.',84,'New Application: Roch House',NULL),(28,'2026-10-15 21:14:11.923217',_binary '\0',15,'Anna Jobe has applied for \"Summerstrand Student Village\".\n\nReview the application from your dashboard.',85,'New Application: Summerstrand Student Village',NULL),(29,'2026-10-15 21:18:37.675184',_binary '\0',15,'Elsa Smith has applied for \"New Residence\".\n\nReview the application from your dashboard.',87,'New Application: New Residence',NULL),(30,'2026-10-15 21:19:28.672770',_binary '\0',15,'Elsa Smith has applied for \"Summerstrand Student Village\".\n\nReview the application from your dashboard.',85,'New Application: Summerstrand Student Village',NULL),(31,'2026-10-15 21:21:22.253624',_binary '\0',15,'Elsa Smith has applied for \"Roch House\".\n\nReview the application from your dashboard.',84,'New Application: Roch House',NULL),(32,'2026-10-15 21:23:54.912918',_binary '\0',15,'Aya Zulu has applied for \"Summerstrand Student Village\".\n\nReview the application from your dashboard.',85,'New Application: Summerstrand Student Village',NULL),(33,'2026-10-15 21:26:41.088630',_binary '\0',15,'Aya Zulu has applied for \"Amazing Grace\".\n\nReview the application from your dashboard.',111,'New Application: Amazing Grace',NULL),(34,'2026-10-15 23:15:36.744645',_binary '\0',15,'Dear Ezile Hlomane,\n\nThis serves as an official warning regarding \"Amazing Grace\". The following complaint(s) have been raised:\n\n• Safety: I am formally reporting a serious security concern at this accommodation. The entrance gate has been faulty for several days, allowing unauthorized individuals to access the building and putting residents\' safety at risk. This issue has already been communicated to management, but no action has been taken to resolve it. I am deeply concerned about the lack of urgency in addressing a matter that directly affects residents\' safety. I request immediate intervention to restore proper security and prevent further unauthorized access.\n\nPlease address these issues promptly. Continued unresolved reports may result in suspension of this listing.',111,'Official Warning: Amazing Grace',NULL);
