INSERT INTO `reports` VALUES (7,'I am formally reporting a serious security concern at this accommodation. The entrance gate has been faulty for several days, allowing unauthorized individuals to access the building and putting residents\' safety at risk. This issue has already been communicated to management, but no action has been taken to resolve it. I am deeply concerned about the lack of urgency in addressing a matter that directly affects residents\' safety. I request immediate intervention to restore proper security and prevent further unauthorized access.',111,'Safety','2026-10-15 21:48:52.184412',NULL,34);
/*!40000 ALTER TABLE `reports` ENABLE KEYS */;
UNLOCK TABLES;

