INSERT INTO `reviews` VALUES (4,2,'I am disappointed with this accommodation due to poor security, unauthorized people entering the building, and unacceptable hygiene standards. Residents deserve to feel safe and live in a clean environment. Management needs to improve access control, strengthen security, and ensure regular cleaning. Until these issues are addressed, I would not recommend this accommodation to other students.',_binary '\0',111,1,'Current','2026-10-15 21:46:45.053749',1,34,3,2,_binary '\0',NULL,5),(5,4,'Overall, I have had a good experience at this accommodation. The rooms are comfortable, and the location is convenient for students. However, there is room for improvement, especially regarding security and maintenance. With better communication and quicker responses to residents\' concerns, the accommodation could provide an even better living experience. I would recommend it to other students.',_binary '\0',85,4,'Current','2026-10-15 23:10:33.642247',5,33,4,5,_binary '\0',NULL,1),(6,3,'Excellent stay! The accommodation was clean, comfortable, and well-maintained. The environment was peaceful and student-friendly, and the service was great. I had a wonderful experience and would definitely recommend it to other students!',_binary '\0',85,5,'Current','2026-10-15 23:13:50.104910',5,32,5,5,_binary '\0',NULL,5);
/*!40000 ALTER TABLE `reviews` ENABLE KEYS */;
UNLOCK TABLES;

